<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'||$argc!==2||!is_file($argv[1].'/user/class/user.class.php')){fwrite(STDERR,"Usage: php test_m119_pilot_configuration.php <native-htdocs>\n");exit(1);}
$module=dirname(__DIR__,2).'/custom/chinaplanetoperations/office_expenses';
if(!is_file($module.'/class/OfficeExpensePilotConfiguration.php')){fwrite(STDERR,"FAIL trusted pilot configuration is missing\n");exit(1);}
require __DIR__.'/fixtures/m119_native_bootstrap.php';require __DIR__.'/fixtures/m119_native_identity.php';
require $module.'/class/OfficeExpensePilotConfiguration.php';
$passed=0;$failed=0;
function pcheck($actual,$expected): void {if($actual!==$expected)throw new RuntimeException('Pilot assertion differs.');}
function preject(callable $action,string $type=DomainException::class): void {try{$action();}catch(Throwable $e){if($e instanceof $type)return;throw $e;}throw new RuntimeException('Expected denial.');}
function ptest(string $name,callable $action): void {global $passed,$failed;try{$action();echo "PASS $name\n";$passed++;}catch(Throwable $e){$failed++;fwrite(STDERR,"FAIL $name: ".$e->getMessage()."\n");}}
function pconfig(): array {return array('version'=>1,'enabled'=>true,'environment'=>'backup-erp','entity'=>1,'user_id'=>7,'base_currency'=>'EGP','offices'=>array('egypt'=>array('EGP'),'china'=>array('CNY')),'precision'=>array('EGP'=>2,'CNY'=>2,'USD'=>2),'private_root'=>'/var/lib/chinaplanetos-office-expenses/receipts');}
function pidentity(): User {m119IdentityDatabase();$u=m119FetchIdentity('synthetic-7');$u->admin=1;return $u;}

ptest('approved native administrator receives only explicit Egypt China office currencies',function(){global $conf;$u=pidentity();$c=new OfficeExpensePilotConfiguration(pconfig());pcheck($c->scope($u,$conf),array('egypt'=>array('EGP'),'china'=>array('CNY')));pcheck($c->privateRoot(),'/var/lib/chinaplanetos-office-expenses/receipts');pcheck($c->precision(),array('EGP'=>2,'CNY'=>2,'USD'=>2));});
ptest('another administrator is denied despite its existing native administrator rights',function(){global $conf;$u=pidentity();$u->id=8;preject(function()use($u,$conf){(new OfficeExpensePilotConfiguration(pconfig()))->scope($u,$conf);},OfficeExpensePilotAccessDenied::class);});
ptest('pilot requires the approved native administrator and enabled valid internal identity',function(){foreach(array('admin','status','external','future')as$case){global $conf;$u=pidentity();if($case==='admin')$u->admin=0;elseif($case==='status')$u->status=0;elseif($case==='external')$u->socid=99;else$u->datestartvalidity=time()+86400;preject(function()use($u,$conf){(new OfficeExpensePilotConfiguration(pconfig()))->scope($u,$conf);},OfficeExpensePilotAccessDenied::class);}});
ptest('entity base currency and module state must match trusted native configuration',function(){foreach(array('entity','currency','module')as$case){global $conf;$u=pidentity();if($case==='entity')$conf->entity=2;elseif($case==='currency')$conf->currency='CNY';else$conf->expensereport->enabled=0;preject(function()use($u,$conf){(new OfficeExpensePilotConfiguration(pconfig()))->scope($u,$conf);});}});
ptest('disabled malformed unknown or widened pilot configuration is refused',function(){foreach(array('disabled','user','entity','version','environment','unknown','offices','currencies','precision','root')as$case){$c=pconfig();if($case==='disabled')$c['enabled']=false;elseif($case==='user')$c['user_id']='7';elseif($case==='entity')$c['entity']=0;elseif($case==='version')$c['version']=2;elseif($case==='environment')$c['environment']='production';elseif($case==='unknown')$c['grant_all']=true;elseif($case==='offices')$c['offices']['other']=array('USD');elseif($case==='currencies')$c['offices']['china']=array('CNY','USD');elseif($case==='precision')$c['precision']['CNY']=3;else$c['private_root']='/var/www/html/uploads';preject(function()use($c){new OfficeExpensePilotConfiguration($c);},InvalidArgumentException::class);}});
ptest('ordinary objects and changed cached native identities cannot expand pilot scope',function(){global $conf;$u=pidentity();$c=new OfficeExpensePilotConfiguration(pconfig());$c->scope($u,$conf);$u->id=8;preject(function()use($c,$u,$conf){$c->scope($u,$conf);},OfficeExpensePilotAccessDenied::class);preject(function()use($c,$conf){$c->scope((object)array('id'=>7,'admin'=>1,'status'=>1),$conf);},OfficeExpensePilotAccessDenied::class);});
ptest('missing web-root symlink or app-owned configuration files never provision storage',function(){
    $base=sys_get_temp_dir().'/m119-pilot-config-'.bin2hex(random_bytes(8));mkdir($base,0700);$file=$base.'/pilot.json';file_put_contents($file,json_encode(pconfig()));chmod($file,0640);symlink($file,$base.'/alias.json');
    try{foreach(array($base.'/missing.json',$base.'/alias.json',$file)as$path)preject(function()use($path,$base){OfficeExpensePilotConfiguration::read($path,$base);},RuntimeException::class);pcheck(file_exists($base.'/receipts'),false);}finally{unlink($base.'/alias.json');unlink($file);rmdir($base);}
});
echo "$passed passed, $failed failed; synthetic native pilot configuration only; no permissions/schema/services changed\n";exit($failed?1:0);
